L000353	 \begin{align}
L000354	 &  E^*(s;\tau)
L000355	\label{Eisen_series_definitions} =\xi(2s)\tau_2^s  +  \xi(2s-1)\, \tau_2^{1-s}\\
L000356	&\notag \phantom{=}+ \sum_{   k\neq0}e^{2\pi i k\tau_1}    2\sqrt{\tau_2}\,  |k|^{s-\half}\sigma_{1-2s} (k)     \, K_{s-\half}(2\pi |k| \tau_2) \,,
