L000547	\section{Sphere partition function for $\mathcal{N}=2^*$ SYM deformed by higher-dimensional operators} \label{eq:part-fun}
L000548	
L000549	Here we review each contribution to the sphere partition function of $\mathcal{N}=2^*$ SYM deformed by higher-dimensional operators, given in \eqref{eq:partition}. For the classical part of the action, we have explicitly
L000550	\begin{align}
L000551	    Z_{\rm classic}(a_i; \tau, \tau') &=\exp \bigg[ {\rm i}\, \pi \tau \, \tr\, a^2 + \sum^\infty_{\substack{p=1 \\ p\neq 2}} {\rm i} \, \pi^{\frac{p}{2}} \tau'_p \, \tr\, a^p \bigg]\, .
L000552	    \end{align}
L000553	We see that $\tau'_1$ is only present for the U$(N)$ theory, since in SU$(N)$ we have $\tr\, a =0$ . The perturbative one-loop determinant contribution is contained in $Z_{\rm 1-loop}(a_i; m)$ and it is given by
L000554	    \begin{align}
L000555	 Z_{\rm 1-loop}(a_i; m) = \frac{1}{H^N(m)} \prod_{i<j} \frac{H^2(a_{ij})}{H(a_{ij}+m)H(a_{ij}-m)} \, ,
L000556	\end{align}
L000557	with $H(x)=e^{-(1+\gamma)x^2} G(1+{\rm i} x)\, G(1-{\rm i} x)$, where $G$ denotes the Barnes $G$-function.
L000558	The instanton contributions, localised at the north and south poles of the 4-sphere, are affected by the higher-dimensional operators and are not known for generic numbers of instantons~\cite{Gerchkovitz:2016gxx}. For the one-instanton sector it is possible to use the analysis of~\cite{Fucito:2015ofa} to derive
L000559	\begin{align}
L000560	& Z_{\rm 1-inst}(a_i; m, \tau, \tau') = -m^2 \sum_{\ell=1}^N \left( \prod_{j \neq \ell} \frac{(a_{\ell j} + {\rm i})^2 -m ^2}{(a_{\ell j} + {\rm i})^2 +1} \right)   \exp \bigg[\! -{\rm i} \sum_{p = 3}^\infty \pi^{\frac{p}{2}} \tau'_p\, (a_{\ell}^p +(a_{\ell} +2 {\rm i})^p -2(a_{\ell} + {\rm i})^p) \bigg] \, .
L000561	\end{align}
L000562	The above expression applies to both SU$(N)$ and U$(N)$ theories, depending on whether we impose the traceless condition $\tr\, a=0$.
L000563	These expressions for $ Z_{\rm 1-loop}(a_i; m) $ and $Z_{\rm 1-inst}(a_i; m, \tau, \tau')$ have been used in the main text to explicitly verify the perturbative and the one-instanton contributions of the exact expressions for the giant graviton integrated correlators.
L000564	
L000565	\section{Further results for the large-$N$ expansion}
L000566	\label{sec:Hooft}
L000567	
L000568	As showed in the main text, the integrated giant graviton correlator expanded at large-$N$ and fixed Yang-Mills coupling $\tau$ takes the following form
L000569	\begin{align} \label{eq:applargeN1}
L000570	    \mathcal{C}_\mathcal{D}(\tau; N)& \sim \widetilde{C}(N) -\widehat{E}(1; \tau) - \sum_{\ell=1}^{\infty} N^{{1 \over 2}-\ell}  \sum_{k=1}^{\ell} c^{(\ell)}_{k}\, E\big(k+ \tfrac{1}{2}; \tau \big)\, .
L000571	    \end{align}
L000572	Here we use a slightly different normalisation for the non-holomorphic Eisenstein series where $ E(s;\tau) = 2E^*(s;\tau)/\Gamma(s)$, and $\widehat{E}(1; \tau)$ denotes the regularised ${E}(1; \tau)$ as given in \eqref{eq:E1}. As discussed in the main text, using \eqref{eq:largeNspec1}-\eqref{eq:largeNspec2} it is straightforward to compute the large-$N$ expansion to any orders. For example, up to $\ell=4$ we find
L000573	\begin{align} \label{eq:clk}
L000574	    \Big\{  c^{(1)}_{1} &= {1 \over 2} \Big\} \, ; \qquad   \Big\{c^{(2)}_{1} = {3 \over 2^5} \, , \quad  c^{(2)}_{2} = - {1 \over 2^3}  \Big\} ; \qquad  \Big\{ c^{(3)}_{1} = {405 \over 2^{12}} \, , \quad  c^{(3)}_{2} = - {9 \over 2^7}\, , \quad  c^{(3)}_{3} =  {25 \over 2^{10}} \Big\} ; \\
L000575	  \Big\{c^{(4)}_{1} &= {7875 \over 2^{15}} \, , \quad   c^{(4)}_{2} = - {2025 \over 2^{14}}\, , \quad  c^{(4)}_{3} =  {105 \over 2^{13}} \, , \quad  c^{(4)}_{4} =  {35 \over 2^{12}} \Big\}\, . \nonumber
L000576	\end{align}
L000577	It is important to note that the perturbative expansions given in \eqref{eq:applargeN1} is an asymptotic, factorially divergent power series in $1/N$ which is not Borel summable. Through resurgence analysis (see e.g. \cite{Dorigoni:2014hea} for introductory notes) this implies the presence of exponentially suppressed terms, as we will discuss below.
L000578	
L000579	On top of the perturbative expansion \eqref{eq:applargeN1}, we also find an infinite number of non-perturbative, modular invariant corrections which we denote by $ \mathcal{C}_\mathcal{D}(\tau; N)\vert_{{\rm NP},f}$ and  $ \mathcal{C}_\mathcal{D}(\tau; N)\vert_{{\rm NP},h}$ originating from the respective spectral overlaps contributions \eqref{eq:largeNspec1} and
L000580	\eqref{eq:largeNspec2}.
L000581	The non-perturbative contributions produced by the large-$N$ expansion of \eqref{eq:largeNspec1} take the form
L000582	\begin{equation}\label{eq:NPDf}
L000583	 \mathcal{C}_\mathcal{D}(\tau; N)\vert_{{\rm NP},f} = \pm i \, \sum_{\ell=0}^\infty N^{\frac{1}{2}-\ell} \sum_{k=0}^{2\ell} d_k^{(\ell)} D_N(k+\tfrac{1-3\ell}{2};\tau)\,,
L000584	\end{equation}
L000585	where the modular invariant function $D_N(s;\tau)$ has been defined in \eqref{eq:DN}.
L000586	The first few coefficients are
L000587	\begin{align}
L000588	&\Big\{ d_0^{(0)} = 4 \Big\}\,,\qquad \Big\{d_0^{(1)}= -\frac{1}{96}\,,\quad d_1^{(1)} = -1\,,\quad d_2^{(1)} = 6 \Big\}\,,\\
L000589	&\notag \Big\{ d_0^{(2)} = \frac{1}{73728}\,,\quad d_1^{(2)} =\frac{1}{384} \,,\quad d_2^{(2)} =\frac{5}{64} \,,\quad d_3^{(2)} = -\frac
L000590	{1}{2}\,,\quad d_4^{(2)} =\frac{5}{2} \Big\}\,.
L000591	\end{align}
L000592	As explained in the main text, the seeming $\pm i$ ambiguity in \eqref{eq:NPDf} is related to the non-Borel summability of \eqref{eq:applargeN1}.
L000593	
L000594	The non-perturbative contributions produced by the large-$N$ expansion of \eqref{eq:largeNspec2} take instead the form
L000595	\begin{equation}\label{eq:NPDh}
L000596	 \mathcal{C}_\mathcal{D}(\tau; N)\vert_{{\rm NP},h} = \sum_{\ell=0}^\infty N^{\frac{3}{4}-\frac{\ell}{2}} \sum_{k=0}^\infty \tilde{d}_k^{(\ell)} D_{\frac{N}{4}}\left( \tfrac{2\ell+1}{4} {-} k ;\tau \right)\,.
L000597	\end{equation}
L000598	The coefficients $\tilde{d}^{(\ell)}_0$, $\tilde{d}^{(\ell)}_1$ for the leading and sub-leading index  $D_{N/4}(s;\tau)$ function are found to be
L000599	\begin{equation}\label{eq:dtilde}
L000600	\tilde{d}^{(\ell)}_0 = \frac{(-1)^{\ell+1} \left(4 \ell^2+3\right) \Gamma \left(\ell-\frac{3}{2}\right) \Gamma \left(\ell+\frac{1}{2}\right)}{\sqrt{\pi } \Gamma (\ell+1)}\,, \qquad \tilde{d}^{(\ell)}_1 =\frac{(-1)^{\ell+1 } \left[16 \ell^4-224 \ell^3+664 \ell^2-424 \ell+9 \right]  \Gamma \left(\ell-\frac{3}{2}\right)^2}{128 \sqrt{\pi } \Gamma (\ell+1)}\,.
L000601	\end{equation}
L000602	
L000603	From the SL$(2, \mathbb{Z})$-invariant results, it is straightforward to extract the 't Hooft large-$N$ expansion. The large-$N$ expansion with fixed 't Hooft coupling $\lambda$ can be expressed as
L000604	\begin{equation}
L000605	\mathcal{C}_{\mathcal{D}}(\tau; N) \sim\mathcal{I}(\lambda) =  \sum_{\ell=0}^\infty N^{1-\ell} \mathcal{I}^{(\ell)}(\lambda)\,,
L000606	\end{equation}
L000607	where the genus-$\ell$ contribution admits the Mellin integral representation
L000608	\begin{equation} \label{eq:IMell}
L000609	\mathcal{I}^{(\ell)}(\lambda)= \int_{\mathcal{C}}  \frac{{\rm d} s}{\pi i} \, \big[f^{(\ell)}(s) + h^{(\ell)}(s) \big] \, \xi(2s)\, \left( \frac{\lambda}{4\pi^2} \right)^{-s} \,,
L000610	\end{equation}
L000611	with $\xi(s) = \pi^{-s/2}\Gamma(\frac{s}{2})\zeta(s)=\xi(1-s)$. The choice of the integration contour $\mathcal{C}$ is described in details after \eqref{eq:Ilambda}.
L000612	Using the expressions for $f^{(\ell)}(s)$ and $h^{(\ell)}(s)$ given in \eqref{eq:fN}, we may derive the large-$N$ expansion with generic fixed $\lambda$ to any given orders.  For the first two orders, $O(N)$ and $O(N^0)$ we reproduce the known results in  \cite{Brown:2024tru}, obtained through a different approach. Below we present the next few orders which are novel expressions in the strong coupling expansion:
L000613	\begin{align}
L000614	     \mathcal{I}^{(2)}  (\lambda) &\sim -\frac{\sqrt{\lambda }}{6} + \frac{3}{2} + \sum_{n=1}^{\infty} \frac{n^2 (2 n{-}7)  \Gamma
L000615	   \left(n{-}\frac{1}{2}\right) \Gamma \left(n {+}\frac{1}{2}\right) \Gamma
L000616	   \left(n {+} \frac{5}{2}\right)  \zeta (2 n{+}1)}{6 \pi ^{3/2} \Gamma (n{+}2)\, \lambda ^{\frac{1}{2} (2 n+1)}}\, , \\
L000617	    \mathcal{I}^{(3)}  (\lambda) &\sim \frac{\sqrt{\lambda }}{24} -\frac{23}{12} - \sum_{n=1}^{\infty} \frac{n^2  \Gamma \left(n{+}\frac{1}{2}\right)^2
L000618	   \Gamma \left(n{+}\frac{7}{2}\right) \zeta (2 n{+}1)}{6 \pi ^{3/2} \Gamma (n{+}2) \, \lambda ^{\frac{1}{2} (2 n+1)}} \, ,  \\
L000619	 \mathcal{I}^{(4)}  (\lambda) &\sim -\frac{\lambda ^{3/2}}{2880} -\frac{25 \sqrt{\lambda }}{3072} +
L000620	   2-\sum_{n=1}^{\infty} \frac{n^2 \left(40 n^3 {-}204 n^2{-}442 n {+} 27\right)
L000621	   \Gamma \left(n{-}\frac{1}{2}\right) \Gamma \left(n{+}\frac{1}{2}\right) \Gamma
L000622	   \left(n{+}\frac{9}{2}\right)\zeta (2 n{+}1)}{11520 \pi ^{3/2} \Gamma (n{+}3)\, \lambda ^{\frac{1}{2} (2 n+1)}}  \, ,  \\
L000623	 \mathcal{I}^{(5)}  (\lambda) &\sim
L000624	 \frac{\lambda ^{3/2}}{3840} -\frac{35 \sqrt{\lambda }}{12288}  -\frac{241}{120}+ \sum_{n=1}^{\infty}\frac{n^2 (20 n^2{+}48 n{+}43)  \Gamma
L000625	   \left(n+\frac{1}{2}\right)^2 \Gamma \left(n{+}\frac{11}{2}\right) \zeta (2 n{+}1)}{11520 \pi ^{3/2} \Gamma
L000626	   (n{+}3) \, \lambda ^{\frac{1}{2} (2 n+1)} }\, .
L000627	\end{align}
L000628	It is easy to verify that these results are in agreement with \eqref{eq:applargeN1}  by considering the zero Fourier mode of the SL$(2, \mathbb{Z})$-invariant results and using the relation $\tau_2 = 4\pi N/ \lambda$.
L000629	Once more, in the above expressions we have omitted exponentially decayed terms of the form $O(e^{-\sqrt{\lambda}})$ and $O(e^{-2\sqrt{\lambda}})$ which can be derived from the large-$s$ asymptotics of the Mellin representation \eqref{eq:IMell} or more directly from the 't Hooft limit of the corresponding SL$(2, \mathbb{Z})$-invariant expressions \eqref{eq:NPDh} and $\eqref{eq:NPDf}$ respectively.
L000630	Importantly, the leading non-perturbative corrections at order $O(N^1)$ can be immediately derived from \eqref{eq:NPDh} by computing the 't Hooft limit of the leading index $D_{N/4}(s;\tau)$ functions, whose coefficients are given in the first equation of \eqref{eq:dtilde}, and they match identically the results of \cite{Brown:2025huy}.
L000631	
